@startuml

class ScientificStaff {
  + PersonID : string
  + PhoneNumber : string
  + Keywords : string[]
}

class ResearchInstitution {
  + InstitutionCode : string
}

class ScientificArticle {
  + DOI : string
  + Title : string
}

class PeerReviewedPaper extends ScientificArticle {
  + CitationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class AuthorPosition {
  + Position : int
}

class Publisher {
  + Name : string
}

class Journal {
  + Name : string
  + ImpactFactor : float
}

class ReviewerAssignment {
}

ScientificStaff "1" -- "0..*" ScientificStaff : author
ScientificStaff "0..*" -- "0..*" ScientificArticle : reviews
ScientificStaff "1" -- "1" ResearchInstitution : works for

ScientificArticle "1" -- "1..*" ScientificArticle : author (via AuthorPosition)
ScientificArticle "1" -- "1..*" ScientificStaff : author (via AuthorPosition)

PeerReviewedPaper "0..*" -- "1" ReviewerAssignment : reviewed by
ReviewerAssignment "0..*" -- "1" ScientificStaff : reviewer

TechnicalReport "0..*" -- "1" ResearchInstitution : published by

Publisher "1" -- "0..*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes to

Journal "1" -- "0..*" PeerReviewedPaper : publishes

class AuthorPosition {
}

@enduml

